export function agentCommandTargetFingerprint(target) {
  if (!target) return null;
  return JSON.stringify([
    target.task_id ?? null,
    target.work_item_id ?? null,
    target.task_status ?? null,
    target.work_item_state ?? null,
    target.provider_thread_id ?? null,
    target.active_turn_id ?? null,
    target.operations ?? []
  ]);
}

export function reconcileAgentCommandDraft(previous = {}, eligibleTargets = []) {
  const priorTargetId = previous.targetTaskId ?? null;
  const requestedTarget = eligibleTargets.find((target) => target.task_id === priorTargetId) ?? eligibleTargets[0] ?? null;
  const nextFingerprint = agentCommandTargetFingerprint(requestedTarget);
  const targetMissing = Boolean(priorTargetId && !eligibleTargets.some((target) => target.task_id === priorTargetId));
  const targetChanged = Boolean(previous.targetFingerprint && nextFingerprint && previous.targetFingerprint !== nextFingerprint);
  const availableOperations = requestedTarget?.operations ?? [];
  const operation = availableOperations.includes(previous.operation) ? previous.operation : availableOperations[0] ?? null;
  const operationChanged = Boolean(previous.operation && operation !== previous.operation);
  const staleReason = targetMissing
    ? `The previous target ${priorTargetId} is no longer eligible. Review the newly selected target before submitting.`
    : targetChanged
      ? "The selected task, Work Item, provider thread, or active turn changed. The draft was kept, but confirmation was cleared."
      : operationChanged
        ? "The previously selected operation is no longer available. Review the replacement operation before submitting."
        : null;
  return {
    targetTaskId: requestedTarget?.task_id ?? priorTargetId,
    operation,
    instruction: String(previous.instruction ?? ""),
    selectionStart: Number.isInteger(previous.selectionStart) ? previous.selectionStart : 0,
    selectionEnd: Number.isInteger(previous.selectionEnd) ? previous.selectionEnd : 0,
    focusedControl: previous.focusedControl ?? null,
    confirmed: staleReason ? false : previous.confirmed === true,
    targetFingerprint: nextFingerprint,
    staleReason
  };
}

export function normalizeDashboardAttention({ observerAttention = [], conditions = [], inbox = {} } = {}) {
  const entries = [];
  for (const item of observerAttention) {
    if (["stale_evidence", "failed_evidence", "approval_pending"].includes(item.type)) continue;
    if (item.type === "unverified_claim") {
      entries.push({
        ...item,
        label: `${item.work_item_id ?? "Work Item"} · Verification pending`,
        message: "A recorded claim still needs independent verification before it can support delivery decisions.",
        suggested_action: "Review verification status",
        jump_view: "system",
        source: "work"
      });
      continue;
    }
    entries.push({ ...item, source: "work" });
  }
  const firingConditions = conditions.filter((item) => item.lifecycle === "firing" && item.status === "true");
  const staleConditions = firingConditions.filter((item) => item.type === "stale-evidence");
  if (staleConditions.length) {
    entries.push({
      type: "stale_evidence",
      count: staleConditions.length,
      label: `${staleConditions.length} verification record${staleConditions.length === 1 ? " needs" : "s need"} refreshing`,
      message: "The code changed after these checks were recorded, so they no longer prove the current revision.",
      suggested_action: "Review verification status",
      jump_view: "system",
      source: "condition"
    });
  }
  for (const item of firingConditions) {
    if (item.type === "stale-evidence") continue;
    entries.push({
      type: item.type,
      work_item_id: item.work_item_id,
      message: item.message,
      suggested_action: item.suggested_action,
      recovery_href: item.recovery_href,
      jump_view: "system",
      source: "condition"
    });
  }
  if (inbox.runtime_permissions?.length) {
    entries.unshift({
      type: "runtime_permission",
      message: `${inbox.runtime_permissions.length} live runtime permission request${inbox.runtime_permissions.length === 1 ? "" : "s"} need an answer.`,
      suggested_action: "Open Human Inbox",
      jump_view: "inbox",
      source: "inbox"
    });
  }
  if (inbox.business_facts?.length) {
    entries.push({
      type: "business_question",
      message: `${inbox.business_facts.length} product or scope question${inbox.business_facts.length === 1 ? "" : "s"} need a human fact.`,
      suggested_action: "Open Human Inbox",
      jump_view: "inbox",
      source: "inbox"
    });
  }
  return entries;
}

export function createRefreshCoordinator(refresh, schedule = (callback) => setTimeout(callback, 40)) {
  let inFlight = null;
  let pending = false;
  let scheduled = false;

  async function load() {
    pending = true;
    if (inFlight) return inFlight;
    inFlight = (async () => {
      do {
        pending = false;
        await refresh();
      } while (pending);
    })();
    try {
      return await inFlight;
    } finally {
      inFlight = null;
    }
  }

  function scheduleLoad() {
    pending = true;
    if (inFlight || scheduled) return;
    scheduled = true;
    schedule(() => {
      scheduled = false;
      void load();
    });
  }

  return { load, scheduleLoad };
}

export function agentModelStatus(snapshot, agentId) {
  const known = (value) => typeof value === "string" && value.length > 0 && !["unknown", "not observed"].includes(value);
  const groups = snapshot?.usage?.driver_groups ?? [];
  const candidates = [];
  for (const item of snapshot?.live_observer?.work?.items ?? []) {
    for (const task of item.tasks ?? []) {
      if (task.agent_id !== agentId) continue;
      const group = groups
        .filter((entry) => entry.dimensions?.task_id === task.id && known(entry.dimensions?.model))
        .sort((left, right) => String(right.last_observed_at ?? "").localeCompare(String(left.last_observed_at ?? "")))[0] ?? null;
      const observedModel = [
        task.effective_model,
        task.usage?.attribution?.model,
        task.usage?.dimensions?.model,
        task.usage?.model,
        group?.dimensions?.model
      ].find(known) ?? null;
      const requestedModel = known(task.requested_model) ? task.requested_model : null;
      const observedStatus = String(task.observed_status ?? task.registered_status ?? "unknown").toLowerCase();
      const isActive = Boolean(
        observedModel &&
        task.visibility === "live" &&
        ["active", "in-progress", "running"].includes(observedStatus)
      );
      const state = isActive ? "active" : observedModel ? "observed" : requestedModel ? "requested" : "unknown";
      const observedAt = group?.last_observed_at ?? task.freshness?.observed_at ?? null;
      const timestamp = Date.parse(observedAt ?? "");
      candidates.push({
        state,
        label: state === "active" ? "Active model" : state === "observed" ? "Last observed" : state === "requested" ? "Requested model" : "No model observation",
        model: observedModel ?? requestedModel,
        requested_model: requestedModel,
        model_version: task.model_version ?? group?.dimensions?.model_version ?? null,
        requested_reasoning_effort: task.requested_reasoning_effort ?? task.usage?.attribution?.requested_reasoning_effort ?? group?.dimensions?.requested_reasoning_effort ?? null,
        observed_thread_reasoning_effort: task.observed_thread_reasoning_effort ?? task.usage?.attribution?.observed_thread_reasoning_effort ?? group?.dimensions?.observed_thread_reasoning_effort ?? null,
        effective_turn_reasoning_effort: task.effective_turn_reasoning_effort ?? task.usage?.attribution?.effective_turn_reasoning_effort ?? group?.dimensions?.effective_turn_reasoning_effort ?? null,
        reasoning_effort: task.reasoning_effort ?? task.usage?.attribution?.reasoning_effort ?? group?.dimensions?.reasoning_effort ?? null,
        reasoning_effort_source: task.reasoning_effort_source ?? task.usage?.attribution?.reasoning_effort_source ?? group?.dimensions?.reasoning_effort_source ?? "unknown",
        work_item_id: item.id ?? task.work_item_id ?? null,
        task_id: task.id ?? null,
        observed_at: observedAt,
        timestamp: Number.isFinite(timestamp) ? timestamp : 0
      });
    }
  }
  if (!candidates.length) {
    return {
      state: "unknown",
      label: "No model observation",
      model: null,
      requested_model: null,
      model_version: null,
      requested_reasoning_effort: null,
      observed_thread_reasoning_effort: null,
      effective_turn_reasoning_effort: null,
      reasoning_effort: null,
      reasoning_effort_source: "unknown",
      work_item_id: null,
      task_id: null,
      observed_at: null
    };
  }
  const ranks = { active: 3, observed: 2, requested: 1, unknown: 0 };
  candidates.sort((left, right) => ranks[right.state] - ranks[left.state] || right.timestamp - left.timestamp || String(left.task_id).localeCompare(String(right.task_id)));
  const { timestamp: _, ...selected } = candidates[0];
  if (selected.state === "unknown") {
    return {
      state: "unknown",
      label: "No model observation",
      model: null,
      requested_model: null,
      model_version: null,
      requested_reasoning_effort: null,
      observed_thread_reasoning_effort: null,
      effective_turn_reasoning_effort: null,
      reasoning_effort: null,
      reasoning_effort_source: "unknown",
      work_item_id: null,
      task_id: null,
      observed_at: null
    };
  }
  return selected;
}

