      deliveryGrid(section,[["Since task creation",deliverySeconds(data.time.task_elapsed_ms)],["Since common entry open",deliverySeconds(data.time.elapsed_ms)],["Before entry (unmeasured)",deliverySeconds(data.time.before_open_unmeasured_ms)],["Local delivery operations",deliverySeconds(data.time.measured_local_operations_ms)],["Explicit pauses",deliverySeconds(data.time.explicit_pause_ms)],["Other elapsed",deliverySeconds(data.time.other_elapsed_ms)]]);
